mapper.select:
SELECT minutes.* FROM oa_meeting_minutes minutes
LEFT JOIN oa_schedule_event meeting ON meeting.tenant_id = minutes.tenant_id
    AND meeting.event_id = COALESCE(minutes.schedule_event_id, minutes.meeting_id) AND meeting.deleted = 0
LEFT JOIN sys_user creator ON creator.tenant_id = meeting.tenant_id AND creator.user_id = meeting.creator_id
WHERE minutes.tenant_id = #{tenantId} AND minutes.deleted = 0
AND minutes.meeting_title LIKE CONCAT('%', #{keyword}, '%')
AND minutes.status = #{status}
AND COALESCE(minutes.schedule_event_id, minutes.meeting_id) = #{meetingId}
AND (COALESCE(minutes.schedule_event_id, minutes.meeting_id) IS NULL OR (meeting.event_id IS NOT NULL AND (
    meeting.creator_id = #{userId}
    OR EXISTS (SELECT 1 FROM oa_meeting_attendance invitation WHERE invitation.tenant_id = meeting.tenant_id
        AND invitation.schedule_event_id = meeting.event_id AND invitation.user_id = #{userId} AND invitation.deleted = 0)
    OR 1 = 1
    OR meeting.creator_id = #{managerUser}

        OR creator.dept_id IN #{departmentId}

))) ORDER BY minutes.meeting_time DESC, minutes.id DESC

mapper.update:
UPDATE oa_meeting_attendance SET minutes_id = #{row.minutesId}, attend_status = #{row.attendStatus},
    check_in_time = #{row.checkInTime}, remark = #{row.remark}, user_name = #{row.userName},
    deleted = #{row.deleted}, update_by = #{row.updateBy}, update_time = #{row.updateTime}
WHERE tenant_id = #{row.tenantId} AND id = #{row.id} AND user_id = #{row.userId}
